const bedOffers=[{size:3,length:3,price:700,title:'Первый огород',text:'Небольшой участок, чтобы попробовать одну культуру.',counts:'Огурцы: 4–6 · томаты: 3–4 · баклажаны: 4–5 · кабачки: 2'},{size:7,length:7,price:1400,title:'Семейная грядка',text:'Больше места для любимой культуры или нескольких зон посадки.',counts:'Огурцы: 10–14 · томаты: 7–9 · баклажаны: 10–12 · кабачки: 4–5'}];
let selectedBedSize=null;
function offerCards(){return `<div class="grid">${bedOffers.map(p=>`<article class="panel"><small>${p.title}</small><h2>1 × ${p.length} м <small>· ${p.size} м²</small></h2><p>${p.text}</p><h3>${p.price.toLocaleString('ru-RU')} ₽ / месяц</h3><small>Предварительная цена аренды · уход и материалы отдельно</small><p><b>Если занять всю грядку одной культурой:</b></p><p>${p.counts} растений.</p><button class="btn" onclick="selectedBedSize=${p.size};location.hash='rent';render();document.getElementById('available-beds')?.scrollIntoView({behavior:'smooth'})">Посмотреть участки ${p.size} м²</button></article>`).join('')}</div><p class="note">Количество растений — ориентир для одного ряда, огурцы и томаты на опорах. Это альтернативные посадки, их нельзя складывать. Сорт, проходы и способ формирования уточняет садовник; для кабачков нужно место для листьев за краями грядки. Урожай в килограммах не гарантируется. <a href="https://extension.umaine.edu/gardening/manual__trashed/planting-chart-home-vegetable-garden/" target="_blank" rel="noopener">Рекомендации по расстояниям</a>. Цены 700 и 1 400 ₽ — стартовая модель, договор аренды и списание за неё пока не подключены.</p>`}
const homeBeforeOnboarding=cloudHome;
cloudHome=function(){if(myPlots().length)return homeBeforeOnboarding();return heading('В вашем хозяйстве ещё нет ни одной грядки.','Выберите размер, посмотрите, что можно вырастить, и найдите свободный участок.')+offerCards()+'<section class="panel"><h3>От грядки до вашего стола</h3><p>Выберите участок → составьте план посадок → закажите уход → наблюдайте за ростом → получите урожай.</p><a class="btn light" href="#rent">Сравнить расходы на сезон</a></section>'};
rent=function(){const plots=account?cloud.plots:[];const available=plots.filter(p=>p.status==='available'&&!p.mine&&(!selectedBedSize||Number(p.size)===selectedBedSize));return heading(myPlots().length?'Добавьте ещё одну грядку.':'В вашем хозяйстве ещё нет ни одной грядки.','Начните с удобной площади. Можно арендовать несколько участков.')+offerCards()+`<section class="panel" id="available-beds"><div class="row"><h2>Свободные участки ${selectedBedSize?selectedBedSize+' м²':''}</h2><button class="btn light" onclick="selectedBedSize=null;render()">Все размеры</button></div>${!account?'<p>Войдите, чтобы увидеть реальные участки фермы.</p><button class="btn" onclick="profile()">Войти / регистрация</button>':available.length?available.map(p=>`<div class="event row"><div><b>Грядка №${p.id}</b><small>${Number(p.size)} м² · условия аренды согласуются с фермой</small></div><button class="btn" onclick="lease(${Number(p.id)})">Выбрать участок</button></div>`).join(''):'<p>Сейчас свободных участков такого размера нет. Фермер добавит их после проверки площади и готовности.</p>'}</section>`+seasonCalculator()};
function seasonCalculator(){return `<section class="panel" style="margin-top:24px"><h2>Сколько будет стоить свой урожай?</h2><p>Измените пример под свой план. Здесь нет обещания, что выращивать всегда дешевле магазина.</p><form id="season-budget" oninput="updateSeasonBudget()"><div class="grid"><label>Аренда в месяц, ₽<input name="rent" type="number" min="0" max="1000000" value="${selectedBedSize===7?1400:700}"></label><label>Месяцев аренды<input name="months" type="number" min="1" max="36" value="5"></label><label>Все работы за сезон, ₽<input name="care" type="number" min="0" max="10000000" value="4000"></label><label>Семена, материалы и доставка, ₽<input name="extras" type="number" min="0" max="10000000" value="1000"></label><label>Ожидаемый урожай, кг · ваш прогноз<input name="yield" type="number" min="0.1" max="100000" step="0.1" value="20"></label><label>Цена сравнимых продуктов в магазине, ₽/кг<input name="shop" type="number" min="1" max="100000" value="250"></label></div><p class="note">Числа в примере — допущения, а не прогноз урожайности или актуальные цены магазина. Введите свои данные. Расходы на работы зависят от культуры и числа заказов.</p><output id="season-result" aria-live="polite"></output></form></section>`}
function updateSeasonBudget(){const form=document.getElementById('season-budget');if(!form)return;const out=document.getElementById('season-result');if(!form.checkValidity()){out.textContent='Введите корректные значения во всех полях.';return}const f=new FormData(form),v=k=>Number(f.get(k));if(['rent','months','care','extras','yield','shop'].some(k=>f.get(k)===''||!Number.isFinite(v(k)))){out.textContent='Заполните все поля расчёта.';return}const total=v('rent')*v('months')+v('care')+v('extras'),per=total/v('yield'),difference=v('shop')*v('yield')-total;out.innerHTML=`<h3>За сезон: ${money(Math.round(total*100))} · ${money(Math.round(per*100))}/кг</h3><p>${difference>=0?'Расчётная экономия':'Дороже магазина на'}: ${money(Math.round(Math.abs(difference)*100))}.</p><p>Чтобы сравняться с магазином при этих расходах, нужно собрать ${(total/v('shop')).toLocaleString('ru-RU',{maximumFractionDigits:1})} кг.</p>`}
const beforeOnboardingRender=render;render=function(){beforeOnboardingRender();updateSeasonBudget()};render();
